import {assessDeal,viabilityDefaults,validateViability,gateLabels,criterionLabels} from './viability.js';
import {gbp,escapeHtml as esc} from './metrics-ui.js';
const num=(v,d=1)=>v===null||!Number.isFinite(v)?'N/A':v.toFixed(d);
const pct=v=>num(v)+'%';
const decision=d=>d==='NO_GO'?'NO-GO':d==='GO'?'GO candidate':'REVIEW';
const icon={GO:'✓',REVIEW:'?',NO_GO:'×'};
const state=s=>({pass:'✓ Pass',fail:'× Fail',unknown:'? Unknown'}[s]);
const valueText=c=>c.key==='dscr'?num(c.value,2)+(c.value===null?'':'×'):['profit','recycled'].includes(c.key)?(c.value===null?'N/A':pct(c.value)):gbp(c.value);
const thresholdText=c=>c.key==='stress'?'Monthly cash flow > £0':c.key==='dscr'?'≥ '+num(c.threshold,2)+'×':['profit','recycled'].includes(c.key)?'≥ '+pct(c.threshold):'≥ '+gbp(c.threshold);
const metric=(label,value,explanation)=>`<div class="viability-metric"><span>${label}</span><strong>${esc(value)}</strong><details><summary>How calculated: ${label}</summary><p>${esc(explanation)}</p></details></div>`;

/** Markup is exported for semantic regression checks; all entered text is escaped. */
export function viabilityMarkup(r,context){
 const b=r.base,d=r.downside;
 return `<div class="viability-heading"><div><div class="eyebrow">DEAL VIABILITY</div><h2>Financial appraisal score</h2><p>${esc(context)} · Spreadsheet inputs and selected assumptions</p></div><div class="viability-decision ${r.finalDecision.toLowerCase()}"><span aria-hidden="true">${icon[r.finalDecision]}</span> ${decision(r.finalDecision)}<small>Financial screen only</small></div></div>
 <div class="viability-score"><div><strong>${r.score}<small>/100</small></strong><progress value="${r.score}" max="100" aria-label="Financial screen score">${r.score}/100</progress></div><p>${r.incomplete?'Incomplete financial inputs — review required.':'No extra manual entries needed for this score.'}<br>Funding and due diligence are separate.</p></div>
 <ul class="viability-reasons">${r.reasons.slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${r.reasons.length>3?`<details><summary>All decision reasons (${r.reasons.length})</summary><ul>${r.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}
 <div class="viability-metrics">
 ${metric('Full capital recovery GDV',gbp(r.minimumGdvForFullRecovery),r.reason||`Required gross loan ${gbp(r.requiredLoan)} ÷ effective LTV ${pct(r.effectiveLtv*100)}. Required loan = equity injected + bridge redemption + other debt repaid + closing costs + advance fees. This reconciles the funding ledger and counts fees once. Full capital recovery threshold, not economic break-even. ${r.equityVerified?'Uses the entered actual equity ledger.':'Uses estimated equity from the appraisal.'}`)}
 ${metric('Expected GDV',gbp(b?.gdv??null),'Selected canonical manual GDV or full-occupancy annual expected rent × multiplier. This is an appraisal assumption, not a verified lender valuation.')}
 ${metric('GDV headroom',`${gbp(r.gdvHeadroom)} / ${r.gdvHeadroomPercent===null?'N/A':pct(r.gdvHeadroomPercent)}`,r.reason||'Expected GDV − full capital recovery GDV. Percentage = headroom ÷ expected GDV × 100. Negative means expected valuation is below the recovery threshold.')}
 ${metric('Cash left in deal',gbp(b?.cashLeftInDeal??null),`Equity injected (${gbp(b?.totalEquityCashInjected??null)}) − signed cash available at refinance (${gbp(b?.cashAvailableAtRefinance??null)}). Positive = capital remaining; negative = extra cash extracted. Net proceeds deduct advance fees, bridge redemption, other debt repaid and closing costs. Actual contributed equity may differ from the modeled funding need.`)}
 ${metric(r.equityVerified?'Capital recycled (actual ledger)':'Estimated capital recycled',r.capitalRecycledPercent===null?'N/A':pct(r.capitalRecycledPercent),`Cash returned to original equity (${gbp(b?.cashReturnedToInvestor??null)}) ÷ equity contributed (${gbp(b?.totalEquityCashInjected??null)}) × 100. Score uses a maximum of 100%. ${r.capitalRecycledPercent>100?`Cash extracted beyond original equity: ${gbp(Math.max(0,-b.cashLeftInDeal))}. `:''}${r.equityVerified?'Uses the entered actual contribution ledger.':'Uses estimated equity or the explicit equity override. No contribution ledger is required unless actual-ledger mode is selected.'}`)}
 ${metric('Downside cash remaining',gbp(d?.cashLeftInDeal==null?null:Math.max(0,d.cashLeftInDeal)),'Positive capital remaining after downside refinance. This is not necessarily new cash you must contribute. Extra cash extracted is shown as negative cash left in the case comparison. Actual contribution ledgers remain fixed; future cost increases are assessed in modeled equity funding needs.')}
 </div>
 <p>Downside additional cash needed at refinance: <b>${gbp(d?.additionalCashRequired??null)}</b>. Downside monthly cash flow: <b>${gbp(d?.monthlyCashFlow??null)}</b>. ${r.overrideProblem?'Reference figures only: loan/payment overrides prevent reliable downside recalculation.':''}</p>
 <details class="viability-detail" data-v-detail="criteria"><summary>Score breakdown — five criteria</summary><div class="table-scroll"><table class="viability-table"><caption class="sr-only">Weighted financial criteria and earned points</caption><thead><tr><th scope="col">Criterion / explanation</th><th scope="col">Value</th><th scope="col">Pass condition</th><th scope="col">Status</th><th scope="col">Points</th></tr></thead><tbody>${r.criteria.map(c=>`<tr><th scope="row">${c.label}<details><summary>How calculated: ${c.label}</summary><p>${esc(criterionFormula(c.key,r))}</p><p>${esc(c.explanation)}</p></details></th><td>${esc(valueText(c))}</td><td>${esc(thresholdText(c))}</td><td>${state(c.status)}</td><td>${c.points}/${c.weight}</td></tr>`).join('')}</tbody></table></div></details>
 <details class="viability-detail" data-v-detail="comparison"><summary>Base case / Downside case</summary><p>The base case is the current appraisal above. The configured downside applies once to it. The downside score re-evaluates the four financial criteria; both scores share the same downside resilience check, without compounding a second stress.</p><div class="table-scroll"><table class="viability-table"><thead><tr><th scope="col">Measure</th><th scope="col">Base case</th><th scope="col">Downside case</th></tr></thead><tbody>${[['Financial score',r.score+'/100',r.downsideScore===null?'N/A':r.downsideScore+'/100'],['GDV',gbp(b?.gdv??null),gbp(d?.gdv??null)],['Cash left in deal',gbp(b?.cashLeftInDeal??null),gbp(d?.cashLeftInDeal??null)],['Monthly cash flow',gbp(b?.monthlyCashFlow??null),gbp(d?.monthlyCashFlow??null)],['Gross refinance advance',gbp(b?.grossRefinanceLoan??null),gbp(d?.grossRefinanceLoan??null)],['Net refinance funds',gbp(b?.netRefinanceFunds??null),gbp(d?.netRefinanceFunds??null)],['Bridging finance cost',gbp(b?.bridge.cost??null),gbp(d?.bridge.cost??null)],['Modeled equity funding need',gbp(b?.fundingRequirement??null),gbp(d?.fundingRequirement??null)],['Additional cash needed at refinance',gbp(b?.additionalCashRequired??null),gbp(d?.additionalCashRequired??null)]].map(([label,a,b])=>`<tr><th scope="row">${label}</th><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div><p>${esc(r.stressExplanation)}</p><p>Configured downside: GDV −${r.downsideAssumptions.gdvDrop}%, build +${r.downsideAssumptions.buildIncrease}%, rent −${r.downsideAssumptions.rentDrop}%, operating costs +${r.downsideAssumptions.operatingIncrease}%, LTV −${r.downsideAssumptions.ltvDrop} percentage points, bridge +${r.downsideAssumptions.extraMonths} months.</p><p>Actual equity contribution ledgers remain fixed; future overrun funding is assessed separately in required committed equity. Original facility and scheduled draws stay fixed; build overruns require equity. Extra months extend bridge interest and holding costs; no rooms earn development-period rent. Stabilised occupancy and reserves stay fixed. Fixed loan/payment overrides are shown for reference and make resilience unknown.</p></details>
 ${fundingMarkup(r)}
 <p class="viability-caveat">Illustrative financial screen, not investment approval or a guarantee. The score does not confirm funding, planning, licensing, valuation evidence or lender eligibility. Optional costs not entered remain zero estimates; review occupancy, management and missing operating costs.</p>`;
}
export const fundingLabels={covered:'Funding covered',gap:'Funding gap',not_assessed:'Not assessed'};
export function fundingMarkup(r){
 return `<div class="viability-funding" aria-label="Optional funding check"><div><b>Optional funding check</b><strong>${r.fundingStatus==='covered'?'✓':r.fundingStatus==='gap'?'×':'?'} ${fundingLabels[r.fundingStatus]}${r.fundingStatus==='gap'?' · '+gbp(r.fundingGap):''}</strong></div><p>Modeled downside funds needed: <b>${gbp(r.requiredFunds)}</b>. Investor funds available: <b>${gbp(r.committedEquity)}</b>. Additional buffer: <b>${gbp(r.cashBuffer)}</b>${r.bufferAssumed?' (no additional buffer assumed)':''}.</p><p>${r.requiredFunds===null?'Downside funding cannot be reliably assessed with the current financial inputs or overrides.':r.committedEquity===null?'Enter available investor funds below if you want a funding check.':'Compares available investor funds with modeled downside equity needs, any refinance top-up and the additional buffer.'} This check never changes the financial score. It is not a monthly peak cash-flow forecast.</p></div>`;
}
function fundingEditor(o,name){return `<details class="viability-detail" data-v-detail="funding"><summary>Optional funding check — ${esc(name)}</summary><form data-v-form="funding"><p>Available investor funds include money already invested plus remaining committed funds, excluding bridge borrowing. Nothing here is required for the financial score.</p><div class="viability-fields">${field('committedEquity','Total investor funds available (£)',o.committedEquity,true)}${field('cashBuffer','Additional cash buffer (£; optional, defaults to £0)',o.cashBuffer??0,true)}</div><button type="submit" class="primary">Save funding check</button></form></details>`;}
function criterionFormula(k,r){const b=r.base;return {profit:`(GDV − total project cost) ÷ total project cost × 100. Cost ${gbp(b?.totalProjectCost??null)} includes bridge costs and fixed refinance fees once. Uplift ${gbp(b?.developmentUplift??null)} is unrealised valuation uplift, not realised sale profit; tax and disposal costs excluded.`,recycled:'Cash returned after debt and refinance deductions ÷ original equity contributed × 100. Uses estimated equity unless actual-ledger mode is selected. Zero equity or an incomplete selected actual ledger is N/A. Over-100% recovery is cash extracted; score input is capped at 100%.',cashflow:`(NOI ${gbp(b?.noi??null)} − annual debt service ${gbp(b?.annualDebtService??null)} − separately entered annual reserves) ÷ 12. Before tax. NOI uses occupancy-adjusted rent less entered operating costs and excludes financing. Debt service follows the selected interest-only or repayment model, or explicit payment override.`,dscr:`NOI ${gbp(b?.noi??null)} ÷ annual debt service ${gbp(b?.annualDebtService??null)}. Zero debt service is N/A, governed by the selected policy. Negative NOI fails.`,stress:'Run the configured independent GDV, rent, build, operating cost, LTV and bridge duration shocks through the same canonical financial model. Pass requires downside monthly cash flow > £0. Available investor funds and evidence checks are separate and do not affect these points. Loan/payment overrides that prevent reliable recalculation produce Unknown.'}[k];}
const field=(path,label,value,optional=false,max='')=>`<label>${esc(label)}<input data-v-field="${path}" type="number" value="${value??''}" min="0" ${max?`max="${max}"`:''} step="any" ${optional?'':'required'} placeholder="${optional?'Not entered':''}"></label>`;
export function viabilityEditor(v,index,name){const o=v.options[index];return `${fundingEditor(o,name)}<details class="viability-detail" data-v-detail="gates"><summary>Optional due diligence checklist — ${esc(name)}</summary><p>Saved evidence is preserved for reference, separately for each finance option. These statuses do not change the financial score. A GO candidate financial screen does not override failed checks or grant investment approval.</p><form data-v-form="gates">${Object.entries(gateLabels).map(([k,label])=>{const g=o.gates[k];return `<fieldset><legend>${label}</legend><div class="viability-fields"><label>Status: ${label}<select data-v-gate="${k}" data-v-prop="status">${['unknown','confirmed','failed'].map(s=>`<option value="${s}" ${g.status===s?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></label><label>Evidence date: ${label}<input type="date" data-v-gate="${k}" data-v-prop="date" value="${esc(g.date)}"></label><label>Notes: ${label}<textarea data-v-gate="${k}" data-v-prop="notes" maxlength="4000">${esc(g.notes)}</textarea></label><label>Evidence / reference: ${label}<textarea data-v-gate="${k}" data-v-prop="evidence" maxlength="4000">${esc(g.evidence)}</textarea></label></div></fieldset>`;}).join('')}<button type="submit" class="primary">Save optional checklist</button></form></details>
 <details class="viability-detail" data-v-detail="settings"><summary>Score settings — thresholds, weights & downside</summary><form data-v-form="settings"><p>Illustrative criteria, editable for this venture and shared across both finance options. Full weight is awarded for pass; fail/unknown earns zero. Weights must total 100. Estimated equity is accepted automatically.</p><div class="viability-fields">${Object.entries(criterionLabels).map(([k,label])=>field('weights.'+k,label+' weight (points)',v.weights[k],false,100)).join('')}${Object.entries(v.thresholds).map(([k,value])=>field('thresholds.'+k,criterionLabels[k]+' threshold '+(k==='dscr'?'(×)':k==='cashflow'?'(£/month)':'(%)'),value,false,k==='recycled'?100:'')).join('')}${field('bands.review','REVIEW starts at score',v.bands.review,false,100)}${field('bands.go','GO candidate starts at score',v.bands.go,false,100)}</div><h3>Downside assumptions</h3><div class="viability-fields">${Object.entries({gdvDrop:'GDV reduction (%)',buildIncrease:'Build cost increase (%)',rentDrop:'Rent reduction (%)',operatingIncrease:'Operating cost increase (%)',ltvDrop:'LTV reduction (percentage points)',extraMonths:'Extra bridging months'}).map(([k,label])=>field('downside.'+k,label,v.downside[k],false,['gdvDrop','rentDrop','ltvDrop'].includes(k)?100:'')).join('')}<label>Zero debt service policy<select data-v-select="zeroDebtPolicy"><option value="review" ${v.zeroDebtPolicy==='review'?'selected':''}>N/A — review required</option><option value="passPositiveNoi" ${v.zeroDebtPolicy==='passPositiveNoi'?'selected':''}>Pass only with positive NOI (DSCR N/A)</option></select></label></div><div class="viability-actions"><button type="submit" class="primary">Apply score settings</button><button type="button" data-v-reset>Reset score settings to defaults</button></div><p>Reset preserves all optional evidence and funding entries.</p></form></details>`;}

export function createViabilityUI(root,save){
 root.innerHTML='<div data-v-results></div><div data-v-editors></div><p data-v-feedback role="status" aria-live="polite"></p>';
 let current,signature='';
 const feedback=message=>{root.querySelector('[data-v-feedback]').textContent=message;};
 root.addEventListener('submit',event=>{
  const form=event.target.closest('[data-v-form]');if(!form)return;event.preventDefault();
  try{
   const v=structuredClone(current.project.viability),target=form.dataset.vForm==='settings'?v:v.options[current.index];
   for(const el of form.querySelectorAll('[data-v-field]')){const parts=el.dataset.vField.split('.');let obj=target;for(const part of parts.slice(0,-1))obj=obj[part];obj[parts.at(-1)]=el.value===''?null:Number(el.value);}
   for(const el of form.querySelectorAll('[data-v-select]'))v[el.dataset.vSelect]=el.value;
   for(const el of form.querySelectorAll('[data-v-gate]'))target.gates[el.dataset.vGate][el.dataset.vProp]=el.value;
   save(validateViability(v));feedback('Viability assessment saved on this device.');root.querySelector(`[data-v-form="${form.dataset.vForm}"] button[type="submit"]`).focus();
  }catch(err){feedback(err.message);}
 });
 root.addEventListener('click',event=>{if(event.target.closest('[data-v-reset]')){const v=viabilityDefaults();v.options=structuredClone(current.project.viability.options);save(v);feedback('Default score settings restored. Gate evidence and funding preserved.');root.querySelector('[data-v-reset]').focus();}});
 return (project,index,input,context)=>{
  current={project,index};
  const resultArea=root.querySelector('[data-v-results]'),open=[...resultArea.querySelectorAll('details[open][data-v-detail]')].map(el=>el.dataset.vDetail);
  resultArea.innerHTML=viabilityMarkup(assessDeal(input,project.viability,index),context);
  for(const el of resultArea.querySelectorAll('[data-v-detail]'))el.open=open.includes(el.dataset.vDetail);
  const next=JSON.stringify([project.viability,index,project.options[index].name]);
  if(next!==signature){const editorArea=root.querySelector('[data-v-editors]'),opened=[...editorArea.querySelectorAll('details[open]')].map(el=>el.dataset.vDetail);editorArea.innerHTML=viabilityEditor(project.viability,index,project.options[index].name);for(const el of editorArea.querySelectorAll('[data-v-detail]'))el.open=opened.includes(el.dataset.vDetail);signature=next;feedback('');}
 };
}
